PAGES=('index','foundations','history','ideas','cryptography','consensus','bitcoin','ethereum','transactions','contracts','solidity','token','stablecoins','defi','scaling','applications','security','practice','labs','tools','sources')
NAV={'en':('Overview','Foundations','History','Money & Web3','Cryptography','Consensus','Bitcoin','Ethereum','Transactions','Contracts','Solidity','Create a token','Stablecoins','DeFi','Scaling','Applications','Security','Practice','Labs','Tools','Sources'), 'zh':('总览','区块链原理','历史','货币与 Web3','密码学','共识','Bitcoin','Ethereum','交易与钱包','智能合约','Solidity','发行代币','稳定币','DeFi','扩容与跨链','应用','安全','实践流程','互动练习','工具','资料')}
DESCRIPTIONS=[('Replicated state, blocks and trust assumptions','复制状态、区块与信任假设'),('From timestamping and Bitcoin to programmable networks','从时间戳与 Bitcoin 到可编程网络'),('Monetary sovereignty, permissionlessness, ownership and governance','货币发行权、无需许可、所有权与治理'),('Hashes, signatures, Merkle commitments and public data','哈希、签名、Merkle 承诺与公开数据'),('PoW, PoS, fork choice and finality','PoW、PoS、分叉选择与最终性'),('UTXOs, Script, mining and issuance rules','UTXO、Script、挖矿与发行规则'),('Accounts, EVM, ETH and the execution/consensus split','账户、EVM、ETH 及执行 / 共识分层'),('Keys, gas, nonce, receipts and transaction lifecycle','密钥、Gas、Nonce、回执与交易生命周期'),('Code, state, ABI, events and oracle boundaries','代码、状态、ABI、事件与预言机边界'),('Read and run a complete MessageBoard contract','阅读并运行完整 MessageBoard 合约'),('Deploy a fixed-supply ERC-20 and inspect its powers','部署固定供应 ERC-20 并检查权限'),('USD₮, collateral, redemption and cross-chain identity','USD₮、担保、赎回与跨链身份'),('AMMs, collateralized lending and composability','AMM、抵押借贷与可组合性'),('Ethereum L2, Lightning, bridges, smart wallets and recent Web3 developments','Ethereum L2、闪电网络、桥、智能钱包及近期 Web3 动向'),('Payments, assets, provenance, DAOs and design choices','支付、资产、溯源、DAO 与设计选择'),('Authorization, reentrancy, approvals, MEV and upgrades','授权、重入、代币许可、MEV 与升级'),('Remix VM, a reproducible local project and a testnet checklist','Remix VM、可复现本地项目与测试网流程'),('Hash links, token allowances and constant-product swaps','哈希链接、代币授权与恒定乘积兑换'),('Original developer tools, standards and issuer records','原始开发工具、标准与发行方记录'),('Primary documents with scope and access notes','一手文档及适用范围说明')]
def p(*xs):return ''.join('<p>'+x+'</p>' for x in xs)
def table(head,rows):return '<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(title,text):return '<aside class="callout"><strong>'+title+'</strong><p>'+text+'</p></aside>'
def code(x):return '<pre><code>'+escape(x)+'</code></pre>'
def source_code(name):return code((Path(__file__).parent/'examples/contracts'/name).read_text())

def chapter(page,lang):
    t=lambda en,zh:zh if lang=='zh' else en
    rows=[]
    def add(ident,title,intro,body,refs=(),viz=None):rows.append((ident,title,intro,body,refs,viz))
    if page=='foundations':
        add('state',t('A blockchain is a replicated state machine','区块链是一种复制状态机'),t('Multiple nodes independently check the same ordered transitions.','多个节点独立检查同一有序状态转换。'),p(t('Think of a ledger as a current state plus rules for changing it. A transaction requests a transition; a block groups ordered requests; nodes execute validation rules and update their own copy. Hash-linked blocks help commit to history, while consensus decides which competing history participants accept.','可以把账本理解为当前状态与改变状态的规则。交易请求状态转换，区块组织有序请求，节点执行验证规则并更新自己的副本。哈希链接区块帮助承诺历史，共识决定参与者接受哪条竞争历史。'),t('Signatures alone cannot prevent the same coin from being spent in two conflicting requests. A shared ordering and validity rule must resolve the conflict. A centralized database can also enforce ordering; a public blockchain addresses the harder setting where no single writer is automatically trusted.','仅有签名不能阻止同一枚币用于两个冲突请求。共享排序及有效性规则必须解决冲突。中心化数据库也能执行排序；公链处理的是更难的环境：没有一个写入者被自动信任。')),('eth-blocks','consensus'),'state')
        add('layers',t('Separate the data structure from the network','分开数据结构与网络'),t('The chain is only one component of the system.','链只是系统的一个组件。'),table([t('Layer','层次'),t('Responsibility','职责'),t('Question to ask','应问的问题')],[(t('Cryptography','密码学'),t('Commitments and transaction authorization','承诺与交易授权'),t('What is signed, and which key controls it?','签什么内容，哪个密钥控制？')),(t('Peer network','对等网络'),t('Propagate blocks and transactions','传播区块与交易'),t('Who can censor or delay access?','谁能审查或延迟访问？')),(t('Consensus','共识'),t('Order history and settle competing proposals','排列历史并处理竞争提案'),t('What assumptions protect finality?','什么假设保护最终性？')),(t('Execution','执行'),t('Apply rules to state','对状态应用规则'),t('Can every node verify the result?','每个节点能验证结果吗？')),(t('Applications & governance','应用与治理'),t('User interfaces, upgrades and collective decisions','界面、升级与集体决策'),t('Who retains privileged powers?','谁仍有特殊权限？'))]),('evm','consensus'))
        add('tradeoffs',t('Choose a blockchain when its trust model is useful','在信任模型有用时选择区块链'),t('Replication, public verification and open access come with costs.','复制、公开验证及开放访问都有成本。'),p(t('A blockchain can enable participants who do not share one administrator to verify a common ledger. It usually adds execution cost, limited throughput, exposed metadata and difficult recovery. A hash on a chain proves a commitment was recorded; it does not prove that an uploaded invoice, sensor reading or real-world title was truthful.','区块链可让不共享一个管理员的参与者验证共同账本，但通常增加执行成本、吞吐限制、公开元数据及恢复难度。链上哈希证明某项承诺被记录，不证明上传发票、传感器读数或现实产权真实。'),t('Permissioned networks choose an allowed validator set; permissionless networks allow participation under protocol rules. “Distributed” does not automatically mean decentralized governance or equal influence. Identify the actual validators, upgrade authority and access dependencies.','许可链选择被允许的验证者集合；无需许可网络允许按协议规则参与。“分布式”不自动意味着治理去中心化或影响力平等。应识别实际验证者、升级权限及访问依赖。')),('oracles','web3'))
    elif page=='history':
        add('timeline',t('Ideas precede the first widely deployed cryptocurrency','理念早于第一个广泛部署的加密货币'),t('Read the milestones as changes in capabilities and trust models.','将里程碑读成能力与信任模型的变化。'),table([t('Period','时期'),t('Milestone','里程碑'),t('Learning point','学习重点')],[('1990s',t('Cryptographic timestamping and digital-cash research','密码学时间戳与数字现金研究'),t('Hashes, signatures and scarcity were separate building blocks','哈希、签名与稀缺性原本是分开的构件')),('2008–2009',t('Bitcoin proposal and network launch','Bitcoin 提案与网络启动'),t('Combine open validation, PoW ordering and native issuance','组合开放验证、PoW 排序与原生发行')),('2015',t('Ethereum mainnet launch','Ethereum 主网启动'),t('General-purpose programmable state and contracts','通用可编程状态与合约')),('2020–2021',t('DeFi and token application expansion','DeFi 与代币应用扩展'),t('Composability also propagates dependency failures','可组合性也会传播依赖故障')),('2022 onward',t('Ethereum Merge and continuing L2 development','Ethereum Merge 及持续 L2 发展'),t('Separate execution, consensus and scaling','分开执行、共识与扩容'))]),('bitcoin-paper','eth-history'),'history')
        add('bitcoin-eth',t('Bitcoin and Ethereum pursue different design spaces','Bitcoin 与 Ethereum 处于不同设计空间'),t('Neither is merely a newer version of the other.','两者并非简单的新旧版本。'),p(t('Bitcoin centers on a monetary ledger using UTXOs, a deliberately constrained scripting system and proof-of-work consensus. Ethereum adds general-purpose EVM execution and an account/state model. Its transition to proof of stake changed consensus without making contract execution disappear.','Bitcoin 以货币账本为核心，采用 UTXO、刻意约束的脚本体系及工作量证明。Ethereum 加入通用 EVM 执行与账户 / 状态模型。转向权益证明改变了共识，并未取消合约执行。'),t('Later systems explore different validator sets, execution models and scaling methods. Compare their validation, finality, data availability and governance rather than ranking them by transaction throughput alone. Historical success or a token’s popularity does not establish a protocol’s suitability for a particular application.','后续系统探索不同验证者集合、执行模型与扩容方法。应比较验证、最终性、数据可用性及治理，而不是只按交易吞吐排名。历史成功或代币知名度不能确定协议适合某项应用。')),('bitcoin-guide','evm','pos'))
        add('lessons',t('Separate adoption history from price cycles','分开采用历史与价格周期'),t('Technical progress, speculation and infrastructure maturity are different axes.','技术进展、投机与基础设施成熟度是不同维度。'),p(t('Learn why a capability appeared: smart contracts enable programmable assets; stablecoins connect token transfers to a fiat unit; rollups move computation while retaining an L1 verification path. Do not treat a rising asset price as evidence that any of these mechanisms is sound.','应理解能力为何出现：智能合约支持可编程资产，稳定币将代币转移连接到法币计价单位，Rollup 迁移计算同时保留 L1 验证路径。资产价格上涨不能证明这些机制可靠。'),t('Read primary protocol timelines for dates and deployment details. Upgrade names and future plans change. This atlas teaches durable mechanisms and pins code dependencies; it does not maintain market prices or recommend assets to buy.','日期与部署细节应查原始协议时间线。升级名称与未来计划会变。本网站教授稳定机制并固定代码依赖，不维护市场价格或推荐购买资产。')),('eth-history','scaling'))
    elif page=='ideas':
        add('money',t('Decentralized money relocates authority over issuance','去中心化货币重新分配发行权'),t('The aspiration is rule-based money without one discretionary issuer.','其愿景是不依赖单一自由裁量发行者的规则货币。'),p(t('Bitcoin’s monetary idea challenges dependence on central issuers and payment intermediaries. Participating nodes enforce an issuance schedule and reject invalid blocks, including unauthorized creation of coins. This offers a way to hold and transfer a native asset under public rules, rather than a liability issued by a bank or token company.','Bitcoin 的货币理念挑战对中心发行者及支付中介的依赖。参与节点执行发行计划，拒绝包括未经授权增发在内的无效区块。这提供了按公开规则持有及转移原生资产的方式，而不是银行或代币公司的负债。'),t('“Opposing the dominance of currency issuance” is an ideological position, not a guaranteed technical outcome. Open-source rules can be debated and changed through adoption; mining, custody, software distribution and economic influence can concentrate. Restricting issuance does not guarantee stable purchasing power, and a usable medium of exchange is not automatically a good unit of account.','“对抗货币发行权的统治地位”是理念立场，不是技术保证。开源规则可以经过讨论与采用而改变；挖矿、托管、软件分发及经济影响力仍可能集中。限制发行不保证购买力稳定，可用交换媒介也不自动成为好的计价单位。')),('bitcoin-paper','bitcoin-core','bis-money'),'ideas')
        add('comparison',t('Compare who sets rules and who can intervene','比较谁制定规则、谁能够干预'),t('Decentralization has several dimensions, not one label.','去中心化有多个维度，不是单个标签。'),table([t('Model','模型'),t('Issuance / backing','发行 / 担保'),t('Control and tradeoff','控制与取舍')],[(t('Sovereign currency','主权货币'),t('Monetary institutions and banking system','货币机构与银行体系'),t('Policy flexibility and public institutions; dependence on institutional governance','政策弹性与公共机构，依赖机构治理')),('Bitcoin',t('Native asset with node-enforced issuance rules','由节点执行发行规则的原生资产'),t('Open verification and self-custody; volatility, key loss and concentration remain','开放验证与自托管，仍有波动、密钥丢失及集中问题')),('USD₮ / USDT',t('Issuer-managed token linked to reserve and redemption arrangements','发行方管理、连接储备及赎回安排的代币'),t('Fiat pricing on a blockchain; issuer controls and off-chain dependencies remain','链上法币计价，保留发行方控制及链下依赖'))])+p(t('Institutional monetary literature stresses payment reliability and a common unit of account; permissionless-system proponents stress independent verification and censorship resistance. Read these as different explicit priorities. Neither a blockchain label nor a public institution removes the need to inspect actual powers and failure modes.','机构货币文献强调支付可靠性与共同计价单位；无需许可系统支持者强调独立验证与抗审查。应将其读为不同的明确优先目标。区块链标签或公共机构身份都不能免除检查实际权限与失效方式的必要。')),('bis-money','tether-reserves','tether-legal'))
        add('web3',t('Web3 proposes user-controlled state and ownership','Web3 提出由用户控制状态与所有权'),t('Inspect the whole application, not only its token.','检查整个应用，而不只是代币。'),p(t('Web3 commonly describes applications where keys, contracts and open protocols support user-held assets and portable participation. A wallet can authorize an action without creating a platform account; a DAO can coordinate a treasury through proposals and voting. These are design possibilities, not a universal architecture standard.','Web3 通常描述以密钥、合约及开放协议支持用户持有资产与可迁移参与的应用。钱包可授权操作而不创建平台账户；DAO 可通过提案与投票协调金库。这些是设计可能性，不是统一架构标准。'),t('A dapp can still depend on a centralized website, RPC provider, sequencer, oracle or upgrade key. Token voting can favor large holders, and social decisions often remain off-chain. Ask whether users can independently access, verify, exit and change the system, and who can freeze or upgrade it.','Dapp 仍可能依赖中心化网站、RPC 提供商、排序器、预言机或升级密钥。代币投票可能偏向大持有者，社会决策常在链下。应询问用户能否独立访问、验证、退出及改变系统，以及谁能冻结或升级。')),('web3','dao','scaling'))
    elif page=='cryptography':
        add('hash',t('Hashes commit to bytes, not to truth','哈希承诺字节，不承诺真实'),t('Change the serialized input and the commitment changes.','序列化输入改变，承诺随之改变。'),p(t('A cryptographic hash maps arbitrary bytes to a fixed-length digest. Blocks can commit to their predecessor and transactions through hashes. Bitcoin uses double SHA-256 in important structures; Ethereum commonly uses Keccak-256. These are different algorithms: Keccak-256 is not interchangeable with standardized SHA3-256.','密码学哈希将任意字节映射到固定长度摘要。区块可通过哈希承诺前一区块及交易。Bitcoin 在重要结构中使用双 SHA-256；Ethereum 常用 Keccak-256。这些算法不同，Keccak-256 不能与标准 SHA3-256 互换。'),t('A correctly linked chain can be rewritten and relinked in a toy program. What makes a production history costly or unacceptable to replace is consensus, validation and finality assumptions. A hash of a false statement is still a valid hash.','玩具程序可以重写并重新链接一条链接正确的链。真实历史难以或不允许替换，依赖共识、验证及最终性假设。虚假陈述的哈希仍是有效哈希。')),('bitcoin-guide','evm'),'cryptography')
        add('signatures',t('A signature authorizes a precisely encoded message','签名授权的是精确编码消息'),t('An address identifies a destination or account; it is not a password.','地址标识目的地或账户，不是密码。'),p(t('Private keys produce signatures; public information lets validators check them. Signatures bind transaction fields, including relevant network/domain information. Changing recipient, amount or nonce changes the signed request. A signature can be cryptographically valid while authorizing an action the user did not intend.','私钥生成签名，公开信息让验证者检查。签名绑定交易字段，包括相关网络 / 域信息。改变接收方、金额或 Nonce 会改变被签请求。签名可能在密码学上有效，却授权用户并未打算执行的动作。'),t('Wallet seed phrases can derive many keys. Self-custody means the ability to authorize transactions and the responsibility to protect or recover those keys; it does not mean that contracts or stablecoin issuers have no other powers. Read typed data and transaction destinations before signing.','钱包助记词可派生多个密钥。自托管意味着有权授权交易及承担保护 / 恢复密钥的责任，不意味着合约或稳定币发行方没有其他权限。签名前应阅读结构化数据与交易目的地。')),('accounts','eth-tx'))
        add('merkle',t('Merkle commitments support compact inclusion checks','Merkle 承诺支持紧凑包含检验'),t('A proof is meaningful relative to a trusted or verified root.','证明只在可信或已验证根的前提下有意义。'),p(t('A Merkle tree combines child hashes into parent commitments. An inclusion proof supplies the sibling values needed to reconstruct a root from one leaf. The root must itself be connected to an accepted block or state; otherwise a producer can make a consistent tree of invented data.','Merkle 树把子哈希组合成父承诺。包含证明提供从一个叶子重建根所需的兄弟值。根本身必须连接到被接受区块或状态，否则生产者可为虚构数据建立一致树。'),t('Blockchains use different commitment structures and serialization rules. Inclusion does not prove that a transaction succeeded, that an off-chain statement is true, or that the block is final. A light client needs a method to validate the relevant header and consensus state.','不同区块链使用不同承诺结构与序列化规则。包含不证明交易成功、链下陈述真实或区块已最终确认。轻客户端需要验证相关区块头及共识状态的方法。')),('bitcoin-guide','eth-blocks'))
    elif page=='consensus':
        add('separate',t('Validity, ordering and finality solve different problems','有效性、排序与最终性解决不同问题'),t('A producer proposes; validating nodes still check the rules.','生产者提议，验证节点仍检查规则。'),p(t('Execution rules say whether a transaction or block is valid. Consensus mechanisms coordinate which valid history to follow when proposals conflict. Finality describes the conditions under which reverting an accepted history becomes unlikely, costly or forbidden under assumptions. A majority cannot simply make invalid coin creation valid to nodes enforcing unchanged rules.','执行规则判断交易或区块是否有效。共识机制在提案冲突时协调跟随哪条有效历史。最终性描述在假设下撤销已接受历史变得不太可能、代价高或不允许的条件。多数参与者不能简单地让执行未变规则的节点接受无效增发。'),t('Temporary forks arise when participants see different proposals or network conditions. Reorganizations can remove previously observed inclusion. Applications should distinguish pending, included, confirmed and finalized states instead of treating the first receipt as permanent settlement.','参与者看到不同提案或网络条件时可出现临时分叉。重组可能移除先前观察到的包含。应用应区分待处理、已包含、已确认及已最终确认，而不是把首个回执视为永久结算。')),('consensus','eth-tx'),'consensus')
        add('pow-pos',t('PoW and PoS put different resources at stake','PoW 与 PoS 使用不同约束资源'),t('Compare mechanisms and assumptions, not slogans.','比较机制与假设，而不是口号。'),table([t('Dimension','维度'),'PoW','PoS'],[(t('Proposal / influence','提案 / 影响力'),t('Computational work under difficulty rules','按难度规则完成计算工作'),t('Stake-weighted validator participation under protocol rules','按协议规则以权益加权参与')),(t('Security resource','安全资源'),t('Hashing capacity and operating costs','哈希算力及运行成本'),t('Locked stake, penalties and validator behavior','锁定权益、惩罚及验证者行为')),(t('History selection','历史选择'),t('Bitcoin selects greatest accumulated work among valid chains','Bitcoin 在有效链中选择累计工作量最大者'),t('Ethereum combines fork choice with checkpoint finality','Ethereum 将分叉选择与检查点最终性组合')),(t('Concentration pressure','集中压力'),t('Pools, hardware and energy access','矿池、硬件及能源获得能力'),t('Large holders, staking services and infrastructure','大持有者、质押服务及基础设施'))]),('bitcoin-guide','pos'))
        add('attacks',t('Consensus security is not application security','共识安全不等于应用安全'),t('An honest network can faithfully execute a vulnerable contract.','诚实网络也会忠实执行有漏洞合约。'),p(t('Ordering attacks may censor or reorder transactions without forging another user’s signature. Network partitions can threaten liveness; validator concentration can affect censorship resistance. The scope of an attacker depends on the protocol and resources, not just a generic “51%” label.','排序攻击可能审查或重排交易，而无需伪造其他用户签名。网络分区可影响活性，验证者集中可影响抗审查。攻击者能力依赖协议及资源，不只是通用“51%”标签。'),t('Even perfectly agreed execution can transfer assets to the wrong recipient if contract logic, signatures or front-end instructions are wrong. Analyze consensus, contract authorization and user interaction separately. Immutable execution amplifies the importance of checking what was actually authorized.','即使执行完全达成一致，合约逻辑、签名或前端指令错误也可能把资产转给错误接收方。应分别分析共识、合约授权及用户交互。不可变执行放大了检查实际授权内容的重要性。')),('mev','security'))
    elif page=='bitcoin':
        add('utxo',t('Bitcoin spends outputs, not a mutable account balance','Bitcoin 花费输出，不是修改账户余额'),t('A wallet’s balance aggregates outputs it can spend.','钱包余额汇总其可花费输出。'),p(t('A transaction consumes existing unspent transaction outputs and creates new outputs with spending conditions. Inputs authorize spending through the relevant script/witness rules. Outputs can pay a recipient and return change to the sender. The fee is the difference between input and output values.','交易消耗现有未花费交易输出，并创建带花费条件的新输出。输入按相关脚本 / 见证规则授权花费。输出可支付接收方并向发送者找零。费用是输入值与输出值之差。'),t('Teaching example: spend a 0.50 BTC output, create 0.20 BTC for a recipient and 0.2999 BTC change; the difference is 0.0001 BTC in fees. These are accounting examples, not current fee quotes. Reusing addresses and combining inputs can expose relationships even though names are not stored in the ledger.','教学例子：花费 0.50 BTC 输出，创建 0.20 BTC 接收输出及 0.2999 BTC 找零，差额 0.0001 BTC 为费用。这是账务示例，不是当前费用报价。即使账本不记录姓名，复用地址及合并输入也可能暴露关系。')),('bitcoin-tx',),'bitcoin')
        add('issuance',t('Mining proposes blocks; nodes enforce monetary rules','挖矿提议区块，节点执行货币规则'),t('The reward schedule is not a miner’s discretionary printing right.','奖励计划不是矿工自由印币权。'),p(t('Bitcoin’s block subsidy halves every 210,000 blocks under the adopted rules, leading toward a roughly 21 million BTC limit. Miners receive the allowed subsidy plus transaction fees through a coinbase transaction. Nodes reject excess subsidy; fees redistribute existing value rather than creating additional subsidy.','按已采用规则，Bitcoin 区块补贴每 210,000 个区块减半，趋向约 2,100 万 BTC 上限。矿工通过 coinbase 交易获得允许补贴及交易费。节点拒绝超额补贴；交易费重新分配已有价值，而非额外创造补贴。'),t('The rules are implemented by software and maintained through network adoption. A fork can propose different rules, but cannot force unchanged validating nodes to accept them. Monetary scarcity is one property; demand, purchasing power and liquidity are separate questions.','规则由软件实现并通过网络采用维持。分叉可以提出不同规则，却不能强迫未改变的验证节点接受。货币稀缺性是一项属性，需求、购买力及流动性是另一类问题。')),('bitcoin-guide','bitcoin-core'))
        add('script',t('Bitcoin is programmable, with a different execution model','Bitcoin 可编程，但执行模型不同'),t('Script conditions are not the same as an EVM application.','Script 条件不等同于 EVM 应用。'),p(t('Bitcoin supports spending conditions such as signature checks and time constraints. Its UTXO model, script rules and transaction validation are distinct from a globally persistent Solidity contract. Learn the exact transaction type and script semantics before translating Ethereum terminology into Bitcoin.','Bitcoin 支持签名检查、时间约束等花费条件。其 UTXO 模型、脚本规则及交易验证不同于全局持久化 Solidity 合约。将 Ethereum 术语套入 Bitcoin 前，应理解具体交易类型与脚本语义。'),t('Off-chain payment protocols add their own channel and settlement mechanisms. A transaction shown by an explorer is an observation of that service; a full node validates rules directly. Wallet software may rely on external infrastructure without the user running a node.','链下支付协议加入自身通道及结算机制。浏览器显示交易是该服务的观察，全节点则直接验证规则。钱包软件可能依赖外部基础设施，而用户并未运行节点。')),('bitcoin-tx','bitcoin-core'))
    elif page=='ethereum':
        add('accounts',t('Ethereum execution changes account and contract state','Ethereum 执行改变账户及合约状态'),t('ETH is the native asset; a token is contract-managed state.','ETH 是原生资产，代币是由合约管理的状态。'),p(t('Ethereum accounts have addresses and state such as balances and nonces; contracts also have code and storage. A signed user transaction can transfer ETH, deploy code or call an existing contract. Token balances commonly live in a contract mapping rather than in a separate native coin ledger.','Ethereum 账户具有地址、余额及 Nonce 等状态；合约另有代码与存储。用户签名交易可转移 ETH、部署代码或调用已有合约。代币余额通常保存在合约映射中，而不是独立原生币账本。'),t('An EOA is traditionally key-controlled; a contract account follows code. Modern account-abstraction mechanisms add programmable account behavior, so the distinction is a starting model rather than the full design space. A wallet is software for constructing and authorizing actions.','EOA 传统上由密钥控制，合约账户按代码执行。现代账户抽象机制加入可编程账户行为，因此两者分类是入门模型，而非完整设计空间。钱包是构建及授权动作的软件。')),('accounts','evm'),'ethereum')
        add('execution',t('EVM bytecode, state and gas form a deterministic computation','EVM 字节码、状态与 Gas 构成确定性计算'),t('Validators must be able to reproduce the same transition.','验证者必须能够复现相同转换。'),p(t('Solidity source is compiled into bytecode plus an ABI. The EVM executes bytecode against an initial state and transaction context, meters work using gas, and either commits allowed changes or reverts the execution’s state changes. Determinism excludes direct arbitrary web requests and ordinary system randomness.','Solidity 源码编译为字节码与 ABI。EVM 在初始状态及交易上下文上执行字节码，以 Gas 计量工作，提交允许改变或回滚执行产生的状态变化。确定性要求排除直接任意网页请求及普通系统随机数。'),t('Storage persists across transactions; memory and calldata serve different execution roles. Events enter transaction logs for off-chain indexing. An event is not a replacement for contract state, and contracts do not query old logs as a general internal database.','Storage 跨交易持久化，Memory 与 Calldata 在执行中作用不同。事件进入交易日志用于链下索引。事件不能替代合约状态，合约也不会把旧日志作为通用内部数据库查询。')),('evm','solidity'))
        add('merge',t('Execution and consensus remain separate layers','执行与共识保持分层'),t('The Merge changed Ethereum consensus to proof of stake.','Merge 将 Ethereum 共识改为权益证明。'),p(t('Ethereum moved from proof of work to proof of stake in September 2022. Execution clients process EVM state and transactions; consensus clients coordinate proposals, attestations and finality. A complete node setup connects both responsibilities.','Ethereum 于 2022 年 9 月从工作量证明转向权益证明。执行客户端处理 EVM 状态与交易，共识客户端协调提案、证明及最终性。完整节点组合这两类职责。'),t('L2 scaling is another layer of design, not the same change as PoS. A rollup’s sequencer can order transactions while L1 contracts enforce a specified proof and settlement mechanism. Inspect what data and exit path are available during failures.','L2 扩容是另一层设计，不等同于 PoS 转换。Rollup 排序器可安排交易，L1 合约执行规定的证明与结算机制。应检查故障时可用的数据及退出路径。')),('eth-history','pos','scaling'))
    elif page=='transactions':
        add('lifecycle',t('A transaction has a lifecycle, not just a hash','交易有生命周期，不只是哈希'),t('Authorization, propagation, inclusion and finality are distinct.','授权、传播、包含及最终性不同。'),p(t('The wallet constructs fields such as chain ID, nonce, destination, value, calldata and fee limits; the user authorizes the request. An RPC endpoint broadcasts it, a producer includes it, and execution produces a receipt. A receipt status reports execution success or failure; finality is a later consensus property.','钱包构建 Chain ID、Nonce、目的地、Value、Calldata 及费用限制等字段，用户授权请求。RPC 端点广播，生产者包含，执行产生回执。回执状态报告执行成功或失败，最终性是后续共识属性。'),t('The nonce orders a sender’s transactions and helps prevent replay in that account sequence. The chain ID distinguishes networks. Replacing a pending transaction, indexing lag and reorganizations can change what a front end sees. Check chain, contract address, receipt and relevant state.','Nonce 排列发送者交易，并帮助防止账户序列内重放。Chain ID 区分网络。替换待处理交易、索引延迟及重组可改变前端看到的结果。应检查链、合约地址、回执及相关状态。')),('eth-tx','accounts'),'transactions')
        add('gas',t('Gas quantity and gas price are different units','Gas 数量与 Gas 价格是不同单位'),t('A reverted transaction can still consume gas.','回滚交易仍可能消耗 Gas。'),p(t('Gas units measure execution resources; the price is expressed in wei per gas. For a conventional EIP-1559 transaction, effective price is constrained by the fee cap and base fee plus priority fee. Transaction cost is gas used multiplied by the effective price, not automatically the entire gas limit times the maximum fee.','Gas 单位计量执行资源，价格以每 Gas 的 Wei 表示。常规 EIP-1559 交易的实际价格受费用上限及基础费加优先费约束。交易成本为已使用 Gas 乘实际价格，并非自动等于全部 Gas 上限乘最高费用。'),t('Hypothetical example: 21,000 gas used at 22 gwei/gas costs 0.000462 ETH. The limit bounds available gas, while maxFeePerGas caps price. These numbers illustrate units only; L2 fees can also include an L1 data component.','假设例子：使用 21,000 Gas，价格为 22 Gwei / Gas，费用为 0.000462 ETH。Gas 上限约束可用数量，maxFeePerGas 限制价格。数字只演示单位；L2 费用还可能包含 L1 数据部分。')),('gas','eip1559'))
        add('wallet',t('A wallet’s displayed balance is not the whole trust model','钱包显示余额并非完整信任模型'),t('Self-custody, smart accounts and exchange custody differ.','自托管、智能账户与交易所托管不同。'),p(t('An exchange balance is the exchange’s account record; a self-custodial key authorizes on-chain transactions; a smart account can add recovery and policy logic. A hardware wallet protects key operations but does not determine whether the transaction destination or contract semantics are appropriate.','交易所余额是交易所账户记录；自托管密钥授权链上交易；智能账户可加入恢复及策略逻辑。硬件钱包保护密钥操作，却不会判断交易目的地或合约语义是否合适。'),t('Tokens are identified by chain and contract, not just a ticker. Sending USDT on one network to an incompatible route is not equivalent to transferring the same asset on another network. Never interpret a token appearing in a wallet list as proof of issuer identity or market value.','代币由链及合约标识，而不只是简称。一条链上的 USDT 发送到不兼容路径，不等于另一条链上同资产转移。钱包列表出现代币不证明发行方身份或市场价值。')),('accounts','tether-protocols'))
    elif page=='contracts':
        add('components',t('A contract exposes a programmable state interface','合约暴露可编程状态接口'),t('Code and authority determine what transitions are possible.','代码与权限决定可执行状态转换。'),table([t('Component','组件'),t('Role','作用'),t('Example','示例')],[(t('Constructor','构造函数'),t('Runs during deployment','部署时运行'),t('Set initial owner and message','设置初始所有者及消息')),(t('Storage','存储'),t('Persistent state','持久化状态'),t('A message or balance mapping','消息或余额映射')),(t('ABI','ABI'),t('Function/event encoding interface','函数 / 事件编码接口'),t('setMessage(string)','setMessage(string)')),(t('Access control','访问控制'),t('Restricts who may change state','限制谁可改变状态'),t('Compare msg.sender to owner','比较 msg.sender 与 owner')),(t('Event','事件'),t('Receipt log for observers','供观察者使用的回执日志'),t('MessageChanged(author, text)','MessageChanged(author, text)'))]),('contracts','solidity'),'contracts')
        add('calls',t('A read, transaction and contract-to-contract call differ','读取、交易与合约间调用不同'),t('“No fee to read” does not mean execution has no cost.','“读取无需付费”不意味着执行没有成本。'),p(t('An eth_call asks a node to simulate execution without committing state. A transaction requests an included state change and pays gas. A view function called within another transaction still participates in that transaction’s execution cost. ABI data describes an interface; it does not certify honest behavior.','eth_call 请求节点模拟执行，不提交状态。交易请求被包含的状态变化并支付 Gas。View 函数若在另一交易内被调用，仍参与该交易执行成本。ABI 描述接口，不认证行为诚实。'),t('External calls transfer control to other code; that code can call back, fail or consume gas. Follow the entire call chain and update critical state before risky interactions where the design requires it. Events and revert data are useful observations, but check the resulting state too.','外部调用把控制权转交其他代码，对方可回调、失败或消耗 Gas。应跟踪完整调用链，并在设计需要时先更新关键状态再进行有风险交互。事件与回滚数据是有用观察，也应检查最终状态。')),('evm','sol-security'))
        add('oracles',t('Off-chain facts need an explicit oracle path','链下事实需要明确预言机路径'),t('A contract cannot directly know a price, weather report or legal title.','合约不能直接知道价格、天气报告或法律产权。'),p(t('Oracles publish or deliver external information in a form contracts can consume. Their data source, signer set, update cadence and failure handling become part of application assumptions. A valid oracle signature proves authorization by that signer, not truth of the original measurement.','预言机以合约可消费形式发布或传递外部信息。数据来源、签名者集合、更新周期及故障处理成为应用假设。有效预言机签名证明签名者授权，不证明原始测量真实。'),t('Randomness, automation and cross-chain messages also need careful input mechanisms. Block fields and current pool prices can be influenced in ways an application author must understand. Avoid treating a deterministic machine as an autonomous source of real-world truth.','随机性、自动化与跨链消息同样需要谨慎输入机制。区块字段及当前池价格可能以开发者应理解的方式被影响。不能把确定性机器当作现实真相的自主来源。')),('oracles','security'))
    elif page=='solidity':
        add('example',t('A complete first contract: MessageBoard','第一个完整合约：MessageBoard'),t('Store a public message and permit only its deployer to change it.','保存公开消息，仅允许部署者修改。'),source_code('MessageBoard.sol')+p(t('The constructor initializes owner and message. immutable stores an unchangeable owner value in deployed code semantics; public generates read accessors. setMessage checks the caller, writes state and emits an event. NotOwner is a custom error. There is no payment or hidden data in this example.','构造函数初始化 owner 与 message。Immutable 使所有者值在部署后不可变，Public 生成读取接口。setMessage 检查调用者、写入状态并发出事件。NotOwner 是自定义错误。示例不处理支付，也没有隐藏数据。')),('solidity','remix-run'),'solidity')
        add('language',t('Learn the language through state and calls','通过状态及调用学习语言'),t('Types, data location and visibility describe different properties.','类型、数据位置及可见性描述不同属性。'),table([t('Feature','特性'),t('Meaning in this example','本例含义')],[('address',t('An account/contract address, not an identity certificate','账户 / 合约地址，不是身份证明')),('msg.sender',t('Immediate caller of the current call; can be another contract','当前调用的直接调用者，可以是另一合约')),('string memory',t('Constructor input used in temporary memory','构造输入位于临时内存')),('string calldata',t('Read-only external call input location','只读外部调用输入位置')),('external / public',t('Callable interface versus generated/public access','可调用接口及公共访问接口')),('private',t('Language visibility restriction, not secrecy on a public chain','语言可见性限制，不是公链保密')),('revert',t('Abort execution and undo its state changes; gas can still be charged','终止执行并回滚其状态变化，仍可能收费'))]),('solidity','sol-security'))
        add('acceptance',t('Test the authority boundary, not only the happy path','测试权限边界，而不只是成功路径'),t('The repository includes actual local EVM tests.','仓库包含真实本地 EVM 测试。'),p(t('Acceptance checks: deployment stores the initial message; the owner can change it; the event contains the expected author and text; another account receives NotOwner and cannot change state. A test that only deploys successfully misses the purpose of access control.','验收包括：部署保存初始消息；所有者可修改；事件包含预期作者及文字；其他账户收到 NotOwner 且不能改变状态。只测试部署成功会漏掉访问控制的目的。'),t('The project uses Solidity 0.8.30, optimizer 200 runs and EVM target shanghai. These are pinned teaching settings, not a latest-version claim. Compiler and library upgrades require rechecking warnings, bytecode and behavior. The minimal contract has no upgrade path or ownership-transfer function.','项目使用 Solidity 0.8.30、优化器 200 次及 Shanghai EVM 目标。这是固定教学设置，不是最新版声明。编译器及库升级后需重新检查警告、字节码与行为。最小合约没有升级路径或所有权转移函数。'))+p('<a href="examples.zip" download>'+t('Download the complete project →','下载完整项目 →')+'</a>'),('security','hardhat'))
    elif page=='token':
        add('fixed',t('Create a fixed-supply ERC-20 learning token','创建固定供应 ERC-20 学习代币'),t('A contract deployment creates token state, not a new blockchain.','部署合约创建代币状态，不是新建区块链。'),source_code('StudyToken.sol')+p(t('StudyToken inherits a pinned OpenZeppelin ERC20 implementation. Its constructor mints 1,000,000 STUDY to a chosen recipient, with 18 display decimals. Raw supply is 1,000,000 × 10¹⁸ units. No public mint, owner, proxy, transfer tax or sale mechanism is added; transfer and allowance behavior come from the library.','StudyToken 继承固定版本 OpenZeppelin ERC20。构造函数向指定接收方铸造 1,000,000 STUDY，显示精度为 18 位。原始供应为 1,000,000 × 10¹⁸ 单位。示例没有加入公开增发、所有者、代理、转账税或销售机制；转账及授权行为来自库。'),t('STUDY is an educational token name. Deploying it creates neither backing nor demand, a price, exchange listing or liquidity. Creating a token is different from creating a native coin with its own consensus network, and from operating a stablecoin issuer.','STUDY 是教学代币名称。部署不会创造担保、需求、价格、交易所上架或流动性。创建代币不同于创建具有自身共识网络的原生币，也不同于运营稳定币发行方。')),('oz-erc20','erc20'),'token')
        add('allowance',t('An approval grants a spender a bounded right','授权给予花费方一定权限'),t('approve does not itself transfer tokens.','Approve 本身不转移代币。'),p(t('balanceOf records holdings; transfer moves the caller’s tokens; approve sets an allowance for a spender; transferFrom uses that authorization to move an owner’s tokens. The spender may be a contract or account. Allowance and balance are separate checks, so a large allowance does not create tokens.','balanceOf 记录持有量，transfer 转移调用者代币，approve 设置花费方额度，transferFrom 使用授权转移所有者代币。花费方可以是合约或账户。额度与余额分别检查，大额授权不会创造代币。'),t('Example: authorize 10 STUDY, then the spender transfers 4; remaining ordinary allowance is 6. If the owner has only 3, a request for 4 still fails. Infinite allowances and nonstandard tokens require additional interpretation. Revoke allowances that are no longer needed and identify the spender’s exact contract.','例子：授权 10 STUDY，花费方转移 4，普通剩余额度为 6。若所有者只有 3，请求转移 4 仍失败。无限额度及非标准代币需要另行解释。应撤销不再需要的额度，并确认花费方精确合约。')),('erc20','oz-api'))
        add('flow',t('A token issuance workflow has several independent outputs','代币发行流程有多项独立产出'),t('Specification, deployment and market operation are separate work.','规格、部署及市场运营是不同工作。'),table([t('Step','步骤'),t('Output','产出')],[(t('Specify','定义规格'),t('Name, symbol, units, supply, allocation and every privileged power','名称、符号、单位、供应、分配及全部特殊权限')),(t('Implement and test','实现与测试'),t('Pinned source, successful compilation and positive/negative behavior checks','固定源码、成功编译及成功 / 失败行为检查')),(t('Deploy locally / testnet','本地 / 测试网部署'),t('Chain ID, address, constructor args, receipt and observed supply','Chain ID、地址、构造参数、回执及实际供应')),(t('Publish and verify','公开与验证'),t('Source, dependency versions, compiler settings and contract identity','源码、依赖版本、编译设置及合约身份')),(t('Operate if needed','如需运营'),t('Separate distribution, liquidity and monitoring plans; deployment does not perform them','独立分配、流动性及监控计划，部署不会自动完成'))])+p(t('For a real public issuance, technical deployment is only one part of a broader financial and operational project. This tutorial stops at local/testnet engineering and does not create a sale, pool or public fundraising transaction.','真实公开发行中，技术部署只是更广泛金融及运营项目的一部分。本教程以本地 / 测试网工程为边界，不创建销售、资金池或公开募资交易。')),('wizard','security','networks'))
    elif page=='stablecoins':
        add('designs',t('A stablecoin needs a peg mechanism beyond a token interface','稳定币需要代币接口之外的锚定机制'),t('Ask what can be redeemed, by whom, and against which assets.','询问可以赎回什么、由谁赎回、对应哪些资产。'),table([t('Design','设计'),t('Mechanism','机制'),t('Key dependencies','关键依赖')],[(t('Reserve-backed','储备担保'),t('Issuer creates tokens against reserve/redemption arrangements','发行方按储备 / 赎回安排创建代币'),t('Reserve assets, custody, issuer terms and liquidity','储备资产、托管、发行方条款与流动性')),(t('Crypto-collateralized','加密资产抵押'),t('Locked collateral and liquidation rules','锁定抵押品与清算规则'),t('Collateral value, oracle freshness and liquidation capacity','抵押品价值、预言机新鲜度与清算能力')),(t('Algorithmic / endogenous','算法 / 内生担保'),t('Supply changes or related-token incentives aim to hold a target','供应变化或相关代币激励试图维持目标'),t('Confidence, reflexivity and available external backing','信心、反身性及可用外部担保'))])+p(t('These categories can overlap. A quoted peg on an exchange is a market observation, not the same as a holder’s enforceable ability to redeem with an issuer. A token may trade away from its target even when its smart contract operates correctly.','类别可以重叠。交易所锚定报价是市场观察，不等于持有者能够向发行方行使赎回。即使智能合约正常运行，代币也可能偏离目标价格。')),('stablecoins',),'stablecoins')
        add('usdt',t('USDT combines on-chain transfers with a centralized issuer','USDT 结合链上转移与中心化发行方'),t('Decentralized settlement infrastructure does not remove issuer powers.','去中心化结算基础设施不会消除发行方权限。'),p(t('Tether publishes supported USD₮ protocols, reserve disclosures and service/redemption terms. Those records identify issuer-recognized deployments; the same USDT ticker on another contract is not enough. The on-chain token represents one layer, while reserves, banking, custody and redemption are off-chain arrangements.','Tether 发布 USD₮ 支持协议、储备披露及服务 / 赎回条款。这些记录识别发行方认可部署；另一合约使用同一 USDT 简称并不足够。链上代币是一层，储备、银行、托管及赎回属于链下安排。'),t('Issuer-controlled token implementations can include privileged issuance and restrictions such as freezing/blacklisting under applicable mechanisms. Inspect the exact chain’s implementation and current terms. Reserve attestations are dated disclosures with a scope; they are not continuous on-chain verification of all reserve assets.','发行方控制的代币实现可包含特殊发行权限，以及按相应机制冻结 / 黑名单等限制。应检查具体链实现与当前条款。储备鉴证是具有日期及范围的披露，不是所有储备资产的连续链上验证。')),('tether-protocols','tether-reserves','tether-legal'))
        add('compatibility',t('Chain, contract, units and transfer behavior all matter','链、合约、单位及转账行为都重要'),t('Do not apply the STUDY example’s assumptions to every real token.','不能把 STUDY 示例假设套用于所有真实代币。'),p(t('Ethereum USD₮ and TRON USD₮ live in different execution and fee environments; a transfer needs the relevant network’s fee asset. Check issuer-listed support and exact token contract before interpreting an address. Token decimals are deployment metadata, not universally 18; read the actual contract rather than copying the STUDY settings.','Ethereum USD₮ 与 TRON USD₮ 位于不同执行及费用环境，转账需要对应网络费用资产。解释地址前应核对发行方支持及精确代币合约。精度不是通用 18 位，应读取实际合约，而非照搬 STUDY 设置。'),t('Some existing token contracts omit a standard boolean return or require a zero approval before a new nonzero approval. OpenZeppelin SafeERC20 includes compatibility helpers, but does not make an untrusted token safe in every sense. Read the implementation and test the integration.','部分既有合约缺少标准布尔返回值，或要求先归零再设新非零授权。OpenZeppelin SafeERC20 提供兼容辅助，但不会让不可信代币在所有意义上安全。应阅读实现并测试集成。')),('tether-protocols','oz-api'))
    elif page=='defi':
        add('amm',t('An AMM is a pricing rule over pooled reserves','AMM 是池中储备上的定价规则'),t('A trade changes reserves and therefore changes the marginal price.','交易改变储备，因此改变边际价格。'),p(t('In a simplified constant-product pool, reserves x and y obey x × y = k. Input Δx obtains output Δy according to the pool formula, with fees modifying the effective input. Large trades relative to reserves move the price more. The interactive lab models a v2-style pool rather than concentrated-liquidity designs.','简化恒定乘积池中，储备 x 与 y 满足 x × y = k。输入 Δx 按池公式获得 Δy，费用改变有效输入。相对储备越大的交易，价格影响越大。互动练习模拟 v2 式池，而非集中流动性设计。'),t('Price impact is the effect of your trade on the pool quote; slippage is the difference between expected and executed outcomes. A minimum-output bound can make an unfavorable execution revert. A current pool price is not automatically a trustworthy oracle for lending or settlement.','价格影响是自身交易对池报价的作用；滑点是预期与实际执行结果的差异。最小输出限制可让不利成交回滚。当前池价不自动成为借贷或结算的可信预言机。')),('uniswap','oracles'),'defi')
        add('lending',t('On-chain lending links collateral, debt and liquidation','链上借贷连接抵押品、债务与清算'),t('Borrowing capacity is a risk rule, not free money.','借贷能力是风险规则，不是免费资金。'),p(t('A collateralized protocol tracks supplied assets, debt, oracle values and risk parameters. If debt grows or collateral value falls beyond permitted conditions, liquidation can repay debt against collateral under specified incentives. The mechanism depends on usable prices and execution liquidity.','抵押协议跟踪供应资产、债务、预言机价值及风险参数。债务增长或抵押价值跌落至不允许条件时，清算可按激励安排偿还债务并取得抵押品。机制依赖可用价格与执行流动性。'),t('Supply rates, borrow rates, utilization and liquidation thresholds are different quantities. A flash loan is borrowed and repaid within one transaction under its rules; it can amplify an oracle or logic weakness without by itself being a vulnerability. Inspect each market’s deployed parameters.','供应利率、借贷利率、利用率及清算阈值是不同量。闪电贷按规则在同一交易内借还，可放大预言机或逻辑弱点，但其本身不等于漏洞。应检查具体市场已部署参数。')),('aave','oracles'))
        add('stack',t('Composability also composes dependencies','可组合性也会组合依赖'),t('Follow the asset and authority chain through the entire application.','沿整个应用跟踪资产及权限链。'),p(t('A vault can deposit into a lending market, use a stablecoin and rely on an oracle or bridge. Each layer adds code, keys and liquidity assumptions. A displayed yield may combine variable borrowing demand, temporary rewards and asset-price changes; those should not be merged into one promised return.','金库可存入借贷市场、使用稳定币，并依赖预言机或桥。每层增加代码、密钥及流动性假设。显示收益可能组合变化的借贷需求、临时奖励及资产价格变化，不应合并成一项承诺回报。'),t('Liquidity providers face changes in asset composition and value relative to holding the original assets, in addition to fee revenue. Governance or upgrade powers can alter strategy behavior. A useful diagram includes every dependency and exit path, not just the front-end brand.','流动性提供者除费用收入外，还面对资产构成变化，以及相对原样持有资产的价值变化。治理或升级权限可改变策略行为。有效图解应包含全部依赖与退出路径，而不只是前端品牌。')),('uniswap','aave','bridges'))
    elif page=='scaling':
        from scaling_content import chapter as scaling_chapter
        rows.extend(scaling_chapter(lang))
    elif page=='applications':
        add('uses',t('Applications combine public state with external systems','应用组合公开状态与外部系统'),t('Define what the chain establishes and what remains off-chain.','明确链上确定什么、什么仍在链下。'),table([t('Application','应用'),t('On-chain role','链上作用'),t('Remaining dependency','保留依赖')],[(t('Payments','支付'),t('Signed transfer and common settlement record','签名转移与共同结算记录'),t('Key custody, network access and conversion routes','密钥托管、网络访问及兑换路径')),(t('Tokenized assets','资产代币化'),t('Transfer rules and records','转移规则与记录'),t('Real-world rights, custodian and enforceability','现实权利、托管方及可执行性')),(t('Provenance','溯源'),t('Timestamped commitments and shared updates','带时间承诺及共享更新'),t('Truth of initial data and sensor/operator integrity','初始数据真实性及传感器 / 运营者完整性')),(t('DAO treasury','DAO 金库'),t('Proposal execution and asset-control policies','提案执行与资产控制策略'),t('Participation, vote concentration and off-chain coordination','参与、投票集中及链下协调')),(t('Credentials','凭证'),t('Issuer commitments or revocation state','发行者承诺或撤销状态'),t('Identity binding, privacy and issuer trust','身份绑定、隐私及发行者信任'))]),('contracts','dao','oracles'),'applications')
        add('nft',t('A token record is not every right associated with an object','代币记录不等于物品相关全部权利'),t('Fungible and non-fungible interfaces represent different state models.','同质化及非同质化接口表示不同状态模型。'),p(t('A fungible token tracks interchangeable units; an NFT commonly tracks distinct token IDs and their holders. Metadata or a URI can describe an object without storing the object on-chain. Owning a token does not by itself establish copyright, real-world ownership or permanent availability of linked media.','同质化代币跟踪可互换单位；NFT 通常跟踪独立 Token ID 及持有者。元数据或 URI 可描述物品，而无需把物品本身放在链上。持有代币本身不确定版权、现实所有权或关联媒体永久可用。'),t('For an application design, keep asset semantics separate from transport semantics. Who can update metadata, revoke a credential or change an upgradeable contract? These questions remain even when transfers are publicly visible.','设计应用时，应将资产语义与传输语义分开。谁能更新元数据、撤销凭证或改变可升级合约？即使转移公开可见，这些问题仍存在。')),('contracts','web3'))
        add('decision',t('Start with the coordination problem','从协调问题开始'),t('A shared database may be the better engineering choice.','共享数据库可能是更好的工程选择。'),p(t('Ask whether participants need independent verification, whether one administrator is acceptable, whether public visibility fits the data, and how mistakes are recovered. Use blockchain where its coordination and trust properties solve the actual problem. Do not add a transferable token only because a project is called Web3.','询问参与者是否需要独立验证、是否接受一个管理员、公开可见是否适合数据，以及错误如何恢复。区块链应解决真实协调与信任问题。不能仅因项目称为 Web3 就加入可转移代币。'),t('A good design document states the state-transition rules, authority map, off-chain dependencies, privacy boundaries and exit/recovery mechanisms. Evaluate those separately from fundraising or price narratives.','好的设计文档列出状态转换规则、权限图、链下依赖、隐私边界及退出 / 恢复机制。应独立评估这些内容，不与募资或价格叙事混合。')),('web3','security'))
    elif page=='security':
        add('classes',t('Inspect both code and privileged powers','同时检查代码及特殊权限'),t('Many failures come from valid execution of an unintended action.','许多故障来自对非预期动作的有效执行。'),table([t('Risk','风险'),t('Mechanism','机制'),t('Useful check','有用检查')],[(t('Access control','访问控制'),t('Unauthorized caller changes sensitive state','未授权调用者改变敏感状态'),t('Positive and negative tests for each privileged function','逐项特殊函数成功及拒绝测试')),(t('Reentrancy','重入'),t('External call returns before critical state is settled','关键状态尚未确定，外部调用就返回重入'),t('Analyze call graph, state ordering and a suitable guard','分析调用图、状态顺序及适用防护')),(t('Oracle manipulation','预言机操纵'),t('A manipulable or stale value drives an economic decision','可操纵或陈旧值驱动经济决定'),t('Source, freshness, bounds and failure handling','来源、新鲜度、边界及失败处理')),(t('Approval abuse','授权滥用'),t('A spender can move previously authorized tokens','花费方可转移此前授权代币'),t('Exact spender identity, limited permissions and revocation','精确花费方身份、限制权限及撤销')),(t('Upgrade control','升级控制'),t('An administrator replaces executable logic','管理员替换执行逻辑'),t('Proxy/admin graph, delay and governance controls','代理 / 管理员图、延时与治理控制'))]),('sol-security','security','oz-api'),'security')
        add('ordering',t('Transaction ordering is part of the threat model','交易排序属于威胁模型'),t('A valid transaction may execute in a different context than expected.','有效交易可能在不同于预期的上下文执行。'),p(t('Public pending transactions can reveal a trade before execution. Ordering participants can place other transactions around it, affecting pool state or inclusion. MEV includes several strategies and roles; it is not just one contract bug. Use explicit output bounds and deadlines where the application needs them.','公开待处理交易可能在执行前暴露交易计划。排序参与者可在前后插入其他交易，影响池状态或包含。MEV 涉及多种策略与角色，不只是一个合约漏洞。应用需要时应设置明确输出边界及截止时间。'),t('Signatures, permits and account recovery also need domain separation, nonces and expiry semantics. Replay-safe encoding does not make a malicious approval benign. Front ends and RPC responses are part of the user’s decision path, even if contract execution is deterministic.','签名、Permit 及账户恢复也需要域分离、Nonce 与过期语义。防重放编码不会让恶意授权变得无害。即使执行确定，前端及 RPC 响应仍是用户决策路径的一部分。')),('mev','eth-tx'))
        add('validation',t('Use several forms of verification','采用多种验证方式'),t('Compilation, testing, source verification and audit answer different questions.','编译、测试、源码验证及审计回答不同问题。'),p(t('Compilation checks language and code generation; tests exercise selected behaviors; fuzzing explores inputs and invariants; source verification connects published code/settings to deployed bytecode; review or audit examines broader logic and assumptions. None alone guarantees all economic and operational behavior.','编译检查语言及代码生成；测试检查选定行为；模糊测试探索输入及不变量；源码验证将公开代码 / 设置连接到部署字节码；审查或审计检查更广逻辑及假设。任何一项都不单独保证全部经济及运营行为。'),t('For StudyToken, check supply conservation and both successful and rejected transfers; for MessageBoard, check owner authority and the unchanged state after rejection. For a real financial protocol, extend the scope to oracle behavior, adversarial composition, governance and incident operations.','StudyToken 应检查供应守恒及成功 / 拒绝转账；MessageBoard 应检查所有者权限及拒绝后状态不变。真实金融协议还需扩展至预言机、对抗性组合、治理及事件处置。')),('security','sol-security'))
    elif page=='practice':
        add('remix',t('Path A · Create the first contract in Remix VM','路径 A · 在 Remix VM 创建第一个合约'),t('No browser wallet or real funds are needed for the first run.','首次运行无需浏览器钱包或真实资金。'),table([t('Step','步骤'),t('Action','操作')],[(t('Open','打开'),t('Open the original Remix IDE and create MessageBoard.sol','打开原始 Remix IDE，创建 MessageBoard.sol')),(t('Compile','编译'),t('Paste the contract from the Solidity chapter; choose compiler 0.8.30 and EVM target Shanghai','粘贴 Solidity 章节合约，选择编译器 0.8.30 及 Shanghai EVM 目标')),(t('Deploy','部署'),t('Select a Remix VM environment, account A and an initial string such as "Hello"','选择 Remix VM、账户 A，以及 "Hello" 等初始字符串')),(t('Observe','观察'),t('Read owner/message, call setMessage as A, and inspect the event/receipt','读取 owner / message，用 A 调用 setMessage，检查事件 / 回执')),(t('Reject','拒绝'),t('Switch to account B, try setMessage and confirm rejection with unchanged state','切换 B 尝试 setMessage，确认拒绝且状态未变'))])+p(t('For StudyToken in Remix, replace the npm import with the versioned import below and compile with the same compiler/target. The recipient argument must be a VM account address, not an ENS name or ticker. Read decimals, totalSupply and balanceOf after deployment.','在 Remix 使用 StudyToken 时，将 npm 导入替换为下面带版本导入，以相同编译器 / 目标编译。Recipient 参数须为 VM 账户地址，而非 ENS 名称或简称。部署后读取 decimals、totalSupply 及 balanceOf。'))+code('import {ERC20} from "@openzeppelin/contracts@5.4.0/token/ERC20/ERC20.sol";'),('remix','remix-run','remix-import'),'practice')
        add('local',t('Path B · Run the downloadable local project','路径 B · 运行可下载本地项目'),t('Compilation and contract execution have been tested on a local EVM.','编译及合约执行已在本地 EVM 测试。'),p(t('Download and extract examples.zip. Use a supported Node.js release (tested here with Node 24.10.0). The lockfile pins the dependencies. Compilation uses local solc; Hardhat supplies the local development node. Open two terminals in the extracted project.','下载解压 examples.zip。使用支持的 Node.js 版本（本站验证为 Node 24.10.0）。锁文件固定依赖。编译使用本地 solc，Hardhat 提供本地开发节点。在项目目录打开两个终端。'))+code('npm ci\nnpm run compile\n# Terminal A\nnpm run node\n# Terminal B\nnpm test\nnpm run demo')+p(t('Expected outcomes: two contracts compile; two test suites pass; the demo prints supply 1,000,000 STUDY, Bob balance 29 STUDY, remaining allowance 6 STUDY, and the changed message. Addresses and transaction hashes vary by run. Scripts accept only loopback chain 31337; no seed phrase or private key is required.','预期结果：两个合约编译，两组测试通过；演示显示供应 1,000,000 STUDY、Bob 余额 29 STUDY、剩余授权 6 STUDY 及修改后消息。地址及交易哈希依运行而异。脚本仅接受本机链 31337，无需助记词或私钥。'))+p('<a href="examples.zip" download>'+t('Download runnable examples →','下载可运行示例 →')+'</a>'),('hardhat','local-node','ethers'))
        add('testnet',t('Path C · Understand the public-testnet deployment flow','路径 C · 理解公开测试网部署流程'),t('This is a manual progression after the local checks.','这是完成本地检查后的手动进阶流程。'),p(t('Check current network guidance, then select an application testnet such as Sepolia, a separate test wallet and a suitable faucet/RPC. Obtain test ETH, confirm the chain ID, compile the same pinned source and deploy through a deliberate testnet connection. Inspect constructor arguments, receipt status, address, supply and owner powers.','核对当前网络指南，选择 Sepolia 等应用测试网、独立测试钱包及适用水龙头 / RPC。获取测试 ETH，确认 Chain ID，以固定源码编译，并经明确测试网连接部署。检查构造参数、回执状态、地址、供应及所有者权限。'),t('Publish source and compiler settings for explorer verification where supported; test reads, transfers, approvals and rejection paths with test accounts. Faucets and RPCs may require accounts or impose limits. The provided scripts deliberately do not automate a public deployment or accept production credentials.','可用时公开源码及编译设置进行浏览器验证，用测试账户检查读取、转账、授权及拒绝路径。水龙头 / RPC 可能需要账号或有限制。所提供脚本明确不自动执行公开部署，也不接收生产凭据。'),t('Mainnet deployment, distribution, exchange listing and liquidity provision are separate steps with different consequences. A token deployment does not perform them. Keep this learning exercise distinct from a real asset issuance or sale.','主网部署、分配、交易所上架及提供流动性是具有不同后果的独立步骤。代币部署不会完成这些操作。应将学习练习与真实资产发行或销售分开。')),('networks','remix-run','security'))
    return rows
